<?php $title='Tags';require __DIR__.'/_layout.php';if(!can_manage('tags'))exit('Forbidden');if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$vals=[];foreach(['name', 'slug'] as $f)$vals[] = trim($_POST[$f]??'');$cols=implode(',',['name', 'slug']);$qs=implode(',',array_fill(0,count($vals),'?'));$st=db()->prepare("INSERT INTO tags ($cols) VALUES ($qs)");$st->execute($vals);flash('success','Saved.');redirect('tags.php');}if(isset($_GET['delete'])){db()->prepare("DELETE FROM tags WHERE id=?")->execute([(int)$_GET['delete']]);redirect('tags.php');}$rows=db()->query("SELECT * FROM tags ORDER BY id DESC")->fetchAll();?><div class="toolbar"><h1>Tags</h1></div><form class="form" method="post"><?=csrf_field()?><label>Name</label><input name="name" required><label>Slug</label><input name="slug" required><button>Save</button></form><section class="section"><table class="table"><tr><th>ID</th><th>name</th><th>slug</th><th>Action</th></tr><?php foreach($rows as $r):?><tr><td><?=$r['id']?></td><td><?=e(mb_strimwidth($r["name"]??"",0,80,"…"))?></td><td><?=e(mb_strimwidth($r["slug"]??"",0,80,"…"))?></td><td><a data-confirm="Delete?" href="tags.php?delete=<?=$r['id']?>">Delete</a></td></tr><?php endforeach;?></table></section><?php require __DIR__.'/_footer.php';?>